// https://storybook.js.org/docs/7.0/preact/writing-stories/introduction
import type { Meta, StoryObj } from '@storybook/preact-vite';
import {
  PriceRange as component,
  PriceRangeProps,
} from '@adobe-commerce/elsie/components/PriceRange';

/**
 * Use PriceRanges to display price range.
 *
 * Import the component like this:
 *
 * ```tsx
 * import { PriceRange } from '@adobe-commerce/elsie/components/PriceRange';
 * ```
 *
 */
const meta: Meta<PriceRangeProps> = {
  title: 'Components/PriceRange',
  component,
  argTypes: {
    currency: {
      description: 'Currency of price',
      control: 'select',
      options: ['USD', 'EUR'],
    },
    locale: {
      description: 'Locale of price',
      control: 'select',
      options: ['en-US', 'fr-FR'],
    },
    amount: {
      description: 'Price of a simple product',
      control: 'number',
    },
    variant: {
      description: 'Price display variant',
      control: 'select',
      options: ['default', 'strikethrough'],
    },
    minimumAmount: {
      description: 'Minimum price of a product price range',
      control: 'number',
    },
    maximumAmount: {
      description: 'Maximum price of a product price range',
      control: 'number',
    },
    size: {
      description: 'Size of price',
      control: 'select',
      options: ['small', 'medium', 'large'],
    },
    display: {
      description: 'Price range display option',
      control: 'select',
      options: ['dash', 'from to', 'as low as'],
    },
    specialPrice: {
      description: 'Special price of a product',
      control: 'select',
      options: [undefined, 9.99],
    },
    sale: {
      description:
        'Whether or not to display contrast color for special sale price',
      control: 'boolean',
    },
  },
};

export default meta;

type Story = StoryObj<PriceRangeProps>;

/**
 * Use the component like this to get a price for a simple product:
 *
 * ```tsx
 * <PriceRange
 *    currency: 'USD',
 *    amount: 36.0,
 *    size: 'small',
 *    variant: 'default',
 *    sale: false,
 * />
 * ```
 */

export const SimplePrice: Story = {
  args: {
    currency: 'USD',
    amount: 36.0,
    size: 'small',
    variant: 'default',
    sale: false,
  },
};

/**
 * Use the component like this to get a simple PriceRange:
 *
 * ```tsx
 * <PriceRange
 *    currency: 'USD',
 *    minimumAmount: 56.0,
 *    maximumAmount: 58.0,
 *    size: 'small',
 *    display: 'dash',
 *    sale: false,
 * />
 * ```
 */
export const PriceRangeDash: Story = {
  args: {
    currency: 'USD',
    minimumAmount: 56.0,
    maximumAmount: 58.0,
    size: 'small',
    display: 'dash',
    sale: false,
  },
};

